function validate([nums, k]) {
  if (!Array.isArray(nums) || nums.length < 2 || nums.length > 10000) return 'nums needs 2 to 10^4 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 0 || v > 1000000)) return 'Each value is a whole number from 0 to 10^6.';
  const pairs = nums.length * (nums.length - 1) / 2;
  if (!Number.isInteger(k) || k < 1 || k > pairs) return `k is between 1 and ${pairs}, the number of pairs.`;
  return null;
}

