function smallestDistancePair(nums, k) {
  // Histogram of every pair's distance, then walk it from distance 0 until k pairs are covered.
  let largest = 0;
  for (const v of nums) largest = Math.max(largest, v);
  const tally = new Uint32Array(largest + 1);
  for (let i = 0; i < nums.length; i++)
    for (let j = i + 1; j < nums.length; j++) tally[Math.abs(nums[i] - nums[j])]++;
  let seen = 0;
  for (let d = 0; d <= largest; d++) {
    seen += tally[d];
    if (seen >= k) return d;
  }
  return -1;
}

