function generate(rand, size) {
  const pick = m => Math.floor(rand() * m);
  const n = size === 'large' ? 1500 + pick(501) : 2 + pick(8);
  const roll = rand();
  // Narrow ranges give many equal distances; the full range spreads them out.
  const top = roll < 0.3 ? (size === 'large' ? 1000 : 3) : roll < 0.6 ? 20 : 1000000;
  const nums = Array.from({ length: n }, () => pick(top + 1));
  const pairs = n * (n - 1) / 2;
  const which = rand();
  const k = which < 0.15 ? 1 : which < 0.3 ? pairs : 1 + pick(pairs);
  return [nums, k];
}
